  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// ------------------------------------------------------------\n// 1. Papéis de acesso\n// ------------------------------------------------------------\nmodel Role {\n  id   Int    @id @default(autoincrement())\n  name String @unique // 'ORGANIZER' | 'CLIENT' | 'GATE'\n\n  users User[]\n\n  @@map(\"roles\")\n}\n\n// ------------------------------------------------------------\n// 2. Usuários\n// ------------------------------------------------------------\nmodel User {\n  id                String   @id @default(uuid())\n  roleId            Int      @map(\"role_id\")\n  name              String\n  email             String   @unique\n  passwordHash      String   @map(\"password_hash\")\n  cpf               String   @unique\n  phone             String?\n  birthDate         String?  @map(\"birth_date\") // YYYY-MM-DD\n  profilePictureUrl String?  @map(\"profile_picture_url\")\n  createdAt         DateTime @default(now()) @map(\"created_at\")\n\n  role Role @relation(fields: [roleId], references: [id], onDelete: Restrict)\n\n  // Relações inversas\n  organizedEvents       Event[]           @relation(\"EventOrganizer\")\n  gatekeeperAssignments EventGatekeeper[]\n  reservedSeats         EventSeat[]       @relation(\"ReservedBy\")\n  purchasedTickets      Ticket[]          @relation(\"TicketBuyer\")\n  validatedTickets      Ticket[]          @relation(\"TicketValidator\")\n\n  @@index([roleId])\n  @@map(\"users\")\n}\n\n// ------------------------------------------------------------\n// 3. Locais / Salas\n// ------------------------------------------------------------\nmodel Venue {\n  id               String  @id @default(uuid())\n  name             String\n  address          String\n  hasAssignedSeats Boolean @default(false) @map(\"has_assigned_seats\")\n  totalCapacity    Int     @map(\"total_capacity\")\n\n  seats  Seat[]\n  events Event[]\n\n  @@map(\"venues\")\n}\n\n// ------------------------------------------------------------\n// 4. Assentos físicos do local\n// ------------------------------------------------------------\nmodel Seat {\n  id         String @id @default(uuid())\n  venueId    String @map(\"venue_id\")\n  rowLabel   String @map(\"row_label\") // ex: '16' ou 'D'\n  seatNumber Int    @map(\"seat_number\")\n  gridX      Int    @map(\"grid_x\")\n  gridY      Int    @map(\"grid_y\")\n  seatType   String @default(\"STANDARD\") @map(\"seat_type\")\n  // 'STANDARD' | 'WHEELCHAIR' | 'COMPANION' | 'OBESE' | 'REDUCED_MOBILITY'\n\n  venue Venue @relation(fields: [venueId], references: [id], onDelete: Cascade)\n\n  eventSeats EventSeat[]\n  tickets    Ticket[]\n\n  @@unique([venueId, rowLabel, seatNumber])\n  @@index([venueId])\n  @@map(\"seats\")\n}\n\n// ------------------------------------------------------------\n// 5. Eventos\n// ------------------------------------------------------------\nmodel Event {\n  id                String   @id @default(uuid())\n  organizerId       String   @map(\"organizer_id\")\n  venueId           String   @map(\"venue_id\")\n  title             String\n  description       String?\n  bannerUrl         String?  @map(\"banner_url\")\n  eventType         String   @map(\"event_type\")\n  // 'SHOW' | 'MOVIE' | 'THEATER' | 'FESTIVAL' | 'OTHER'\n  startTime         DateTime @map(\"start_time\")\n  externalApiSource String?  @map(\"external_api_source\") // 'TMDB' | 'TICKETMASTER'\n  externalApiId     String?  @map(\"external_api_id\")\n  status            String   @default(\"PUBLISHED\")\n  // 'DRAFT' | 'PUBLISHED' | 'CANCELLED'\n  createdAt         DateTime @default(now()) @map(\"created_at\")\n\n  organizer User  @relation(\"EventOrganizer\", fields: [organizerId], references: [id], onDelete: Restrict)\n  venue     Venue @relation(fields: [venueId], references: [id], onDelete: Restrict)\n\n  eventSeats  EventSeat[]\n  gatekeepers EventGatekeeper[]\n  ticketTypes TicketType[]\n  tickets     Ticket[]\n\n  @@index([organizerId])\n  @@map(\"events\")\n}\n\n// ------------------------------------------------------------\n// 6. Estado do assento por evento\n// ------------------------------------------------------------\nmodel EventSeat {\n  id                   String    @id @default(uuid())\n  eventId              String    @map(\"event_id\")\n  seatId               String    @map(\"seat_id\")\n  status               String    @default(\"AVAILABLE\")\n  // 'AVAILABLE' | 'RESERVED' | 'SOLD' | 'BLOCKED'\n  reservedById         String?   @map(\"reserved_by_id\")\n  reservationExpiresAt DateTime? @map(\"reservation_expires_at\")\n\n  event      Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  seat       Seat  @relation(fields: [seatId], references: [id], onDelete: Cascade)\n  reservedBy User? @relation(\"ReservedBy\", fields: [reservedById], references: [id], onDelete: SetNull)\n\n  @@unique([eventId, seatId])\n  @@index([eventId, status])\n  @@map(\"event_seats\")\n}\n\n// ------------------------------------------------------------\n// 7. Vínculo de porteiros ao evento\n// ------------------------------------------------------------\nmodel EventGatekeeper {\n  id           String   @id @default(uuid())\n  eventId      String   @map(\"event_id\")\n  gatekeeperId String   @map(\"gatekeeper_id\")\n  assignedAt   DateTime @default(now()) @map(\"assigned_at\")\n\n  event      Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  gatekeeper User  @relation(fields: [gatekeeperId], references: [id], onDelete: Cascade)\n\n  @@unique([eventId, gatekeeperId])\n  @@map(\"event_gatekeepers\")\n}\n\n// ------------------------------------------------------------\n// 8. Tipos de ingresso\n// ------------------------------------------------------------\nmodel TicketType {\n  id                String  @id @default(uuid())\n  eventId           String  @map(\"event_id\")\n  name              String // ex: 'Meia-Entrada', 'Inteira'\n  price             Float\n  description       String?\n  quantityAvailable Int     @map(\"quantity_available\")\n\n  event   Event    @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  tickets Ticket[]\n\n  @@map(\"ticket_types\")\n}\n\n// ------------------------------------------------------------\n// 9. Ingressos comprados e emitidos\n// ------------------------------------------------------------\nmodel Ticket {\n  id            String    @id @default(uuid())\n  eventId       String    @map(\"event_id\")\n  ticketTypeId  String    @map(\"ticket_type_id\")\n  buyerId       String    @map(\"buyer_id\")\n  seatId        String?   @map(\"seat_id\") // null em evento de pista sem assento\n  buyerName     String    @map(\"buyer_name\")\n  accessCode    String    @unique @map(\"access_code\") // código manual da portaria\n  qrCodeToken   String    @unique @map(\"qr_code_token\") // hash assinado (HMAC) do QR\n  shareToken    String    @unique @map(\"share_token\") // token da URL de compartilhamento\n  status        String    @default(\"VALID\")\n  // 'VALID' | 'USED' | 'EXPIRED' | 'CANCELLED'\n  validatedAt   DateTime? @map(\"validated_at\")\n  validatedById String?   @map(\"validated_by_id\")\n  purchasedAt   DateTime  @default(now()) @map(\"purchased_at\")\n\n  event       Event      @relation(fields: [eventId], references: [id], onDelete: Restrict)\n  ticketType  TicketType @relation(fields: [ticketTypeId], references: [id], onDelete: Restrict)\n  buyer       User       @relation(\"TicketBuyer\", fields: [buyerId], references: [id], onDelete: Restrict)\n  seat        Seat?      @relation(fields: [seatId], references: [id], onDelete: Restrict)\n  validatedBy User?      @relation(\"TicketValidator\", fields: [validatedById], references: [id], onDelete: SetNull)\n\n  // Segunda camada de segurança: mesmo assento não pode ser vendido 2x no mesmo evento\n  @@unique([eventId, seatId])\n  @@index([buyerId])\n  @@index([eventId])\n  @@index([accessCode])\n  @@index([qrCodeToken])\n  @@index([shareToken])\n  @@map(\"tickets\")\n}\n"
